import React, { useState } from "react";
import { useNavigate, Link } from "react-router-dom";
import '../styles/AuthStyles.css';
import logo from '../images/logo.png';
import { FaGoogle, FaFacebook, FaTiktok } from "react-icons/fa";

const SignUp = () => {
  const [formData, setFormData] = useState({
    email: "",
    name: "",
    role: "buyer"
  });

  const [error, setError] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const navigate = useNavigate();

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    setError("");
    
    try {
      if (!formData.email || !formData.name) {
        throw new Error("Please fill in all fields");
      }

      // In a real app, you would send this to your backend
      // For now, we'll just proceed to onboarding
      navigate("/onboarding/age-verification", { state: { email: formData.email, name: formData.name } });
    } catch (error) {
      setError(error.message);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSocialSignup = (provider) => {
    window.location.href = `${process.env.REACT_APP_BACKEND_URL}/api/auth/${provider}`;
  };

  return (
    <div className="auth-container">
      <div className="background-slideshow">
        <div className="slide slide1"></div>
        <div className="slide slide2"></div>
        <div className="slide slide3"></div>
      </div>
      
      <div className="auth-content">
        <img src={logo} alt="Folo Logo" className="auth-logo" />
        <div className="auth-form">
          <h1>Sign Up</h1>
          {error && <p className="error-message">{error}</p>}
          
          <form onSubmit={handleSubmit}>
            <div className="form-group">
              <label>Full Name:</label>
              <input
                type="text"
                name="name"
                value={formData.name}
                onChange={handleChange}
                required
                minLength={2}
              />
            </div>
            
            <div className="form-group">
              <label>Email:</label>
              <input
                type="email"
                name="email"
                value={formData.email}
                onChange={handleChange}
                required
              />
            </div>
            
            <div className="form-group">
              <label>I want to:</label>
              <select 
                name="role" 
                value={formData.role}
                onChange={handleChange}
                className="role-select"
              >
                <option value="buyer">Shop on Folo</option>
                <option value="seller">Sell on Folo</option>
              </select>
            </div>
            
            <button type="submit" className="auth-button" disabled={isLoading}>
              {isLoading ? "Creating account..." : "Continue"}
            </button>
          </form>
          
          <div className="divider">
            <span>OR</span>
          </div>
          
          <div className="social-login-buttons">
            <button 
              className="social-btn google"
              onClick={() => handleSocialSignup("google")}
            >
              <FaGoogle /> Continue with Google
            </button>
            
            <button 
              className="social-btn facebook"
              onClick={() => handleSocialSignup("facebook")}
            >
              <FaFacebook /> Continue with Facebook
            </button>
            
            <button 
              className="social-btn tiktok"
              onClick={() => handleSocialSignup("tiktok")}
            >
              <FaTiktok /> Continue with TikTok
            </button>
          </div>
          
          <p className="auth-link">
            Already have an account? <Link to="/login">Log in here</Link>.
          </p>
        </div>
      </div>
    </div>
  );
};

export default SignUp;