import React, { createContext, useState, useEffect, useCallback } from "react";
import axios from "axios";
import PropTypes from "prop-types";

export const AuthContext = createContext();

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [isAuthenticating, setIsAuthenticating] = useState(true);

  useEffect(() => {
    const checkAuth = async () => {
      try {
        const token = localStorage.getItem("token");
        const refreshToken = localStorage.getItem("refreshToken");
        const userData = JSON.parse(localStorage.getItem("userData"));

        if (token && userData) {
          setUser({
            token,
            refreshToken,
            ...userData,
          });
        } else if (refreshToken) {
          await refreshAuth();
        }
      } catch (error) {
        logout();
      } finally {
        setIsAuthenticating(false);
      }
    };
    checkAuth();
  }, []);

  const refreshAuth = useCallback(async () => {
    try {
      const refreshToken = localStorage.getItem("refreshToken");
      if (!refreshToken) throw new Error("No refresh token available");
      const response = await axios.post(`${process.env.REACT_APP_BACKEND_URL}/api/refresh-token`, { refreshToken });
      const { token, refreshToken: newRefreshToken, user: userData } = response.data;
      localStorage.setItem("token", token);
      localStorage.setItem("refreshToken", newRefreshToken);
      localStorage.setItem("userData", JSON.stringify(userData));
      setUser({
        token,
        refreshToken: newRefreshToken,
        ...userData,
      });
      return token;
    } catch (error) {
      logout();
      throw error;
    }
  }, []);

  const login = async (email, password) => {
    try {
      const response = await axios.post(`${process.env.REACT_APP_BACKEND_URL}/api/login`, { email, password });
      const { token, refreshToken, user: userData } = response.data;
      localStorage.setItem("token", token);
      localStorage.setItem("refreshToken", refreshToken);
      localStorage.setItem("userData", JSON.stringify(userData));
      setUser({
        token,
        refreshToken,
        ...userData,
      });
      return { success: true, user: userData };
    } catch (error) {
      throw new Error(error.response?.data?.message || "Login failed. Please check your credentials.");
    }
  };

  const handleSocialLogin = async (provider, token, refreshToken) => {
    try {
      localStorage.setItem("token", token);
      localStorage.setItem("refreshToken", refreshToken);
      const response = await axios.get(`${process.env.REACT_APP_BACKEND_URL}/api/users/profile`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      const userData = response.data.data;
      localStorage.setItem("userData", JSON.stringify(userData));
      setUser({
        token,
        refreshToken,
        ...userData
      });
      return { success: true, user: userData };
    } catch (error) {
      throw error;
    }
  };

  const logout = () => {
    setUser(null);
    localStorage.removeItem("token");
    localStorage.removeItem("refreshToken");
    localStorage.removeItem("userData");
  };

  const deleteAccount = async () => {
    try {
      await axios.post(`${process.env.REACT_APP_BACKEND_URL}/api/account/delete`, {
        userId: user?.id,
        deletionDate: new Date(Date.now() + 14 * 24 * 60 * 60 * 1000),
      }, {
        headers: { Authorization: `Bearer ${user?.token}` }
      });
      logout();
    } catch (error) {
      throw error;
    }
  };

  const updateRole = (newRole) => {
    if (!newRole) return;
    setUser((prev) => {
      if (!prev) return prev;
      const updatedUser = { ...prev, role: newRole };
      localStorage.setItem("userData", JSON.stringify({
        id: updatedUser.id,
        email: updatedUser.email,
        role: newRole,
      }));
      return updatedUser;
    });
  };

  const authAxios = axios.create({
    baseURL: process.env.REACT_APP_BACKEND_URL || "http://localhost:5000",
  });

  authAxios.interceptors.request.use((config) => {
    if (user?.token) {
      config.headers.Authorization = `Bearer ${user.token}`;
    }
    return config;
  }, (error) => Promise.reject(error));

  authAxios.interceptors.response.use((response) => response, async (error) => {
    const originalRequest = error.config;
    if (error.response?.status === 401 && !originalRequest._retry) {
      originalRequest._retry = true;
      try {
        const newToken = await refreshAuth();
        originalRequest.headers.Authorization = `Bearer ${newToken}`;
        return authAxios(originalRequest);
      } catch (refreshError) {
        logout();
        return Promise.reject(refreshError);
      }
    }
    return Promise.reject(error);
  });

  return (
    <AuthContext.Provider value={{
      user,
      isAuthenticating,
      login,
      logout,
      updateRole,
      deleteAccount,
      authAxios,
      handleSocialLogin
    }}>
      {children}
    </AuthContext.Provider>
  );
};

AuthProvider.propTypes = {
  children: PropTypes.node.isRequired,
};