import React, { useState, useContext } from "react";
import { useNavigate } from "react-router-dom";
import { AuthContext } from "../AuthContext";
import { Link } from "react-router-dom";
import axios from "axios";
import '../styles/AuthStyles.css';
import '../styles/global.css';
import logo from '../images/logo.png';
import { FaEye, FaEyeSlash, FaGoogle, FaFacebook, FaTiktok } from "react-icons/fa";

const Login = () => {
  const [formData, setFormData] = useState({
    email: "",
    password: "",
  });

  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const navigate = useNavigate();
  const { login } = useContext(AuthContext);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    setError("");
    
    try {
      if (!formData.email || !formData.password) {
        throw new Error("Please fill in all fields");
      }

      const { success } = await login(formData.email, formData.password);
      
      if (success) {
        navigate("/onboarding/age-verification");
      }
    } catch (error) {
      setError(error.message || "Login failed. Please try again.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleSocialLogin = (provider) => {
    // Redirect to backend social auth endpoint
    window.location.href = `${process.env.REACT_APP_BACKEND_URL}/api/auth/${provider}`;
  };

  const handlePasswordlessLogin = async (email) => {
    try {
      setIsLoading(true);
      const response = await axios.post(`${process.env.REACT_APP_BACKEND_URL}/api/auth/passwordless`, { email });
      alert(response.data.message); // "Magic link sent to your email"
    } catch (error) {
      setError(error.response?.data?.message || "Failed to send magic link");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="auth-container">
      <div className="background-slideshow">
        <div className="slide slide1"></div>
        <div className="slide slide2"></div>
        <div className="slide slide3"></div>
      </div>
      
      <div className="auth-content">
        <img src={logo} alt="Folo Logo" className="auth-logo" />
        <div className="auth-form">
          <h1>Login</h1>
          {error && <p className="error-message">{error}</p>}
          
          <form onSubmit={handleSubmit}>
            <div className="form-group">
              <label>Email:</label>
              <input
                type="email"
                name="email"
                value={formData.email}
                onChange={handleChange}
                required
              />
            </div>
            
            <div className="form-group">
              <label>Password:</label>
              <div className="password-input-container">
                <input
                  type={showPassword ? "text" : "password"}
                  name="password"
                  value={formData.password}
                  onChange={handleChange}
                  required
                />
                <button
                  type="button"
                  className="show-password-button"
                  onClick={() => setShowPassword(!showPassword)}
                >
                  {showPassword ? <FaEyeSlash /> : <FaEye />}
                </button>
              </div>
            </div>
            
            <button type="submit" className="auth-button" disabled={isLoading}>
              {isLoading ? "Logging in..." : "Login"}
            </button>
          </form>
          
          <div className="divider">
            <span>OR</span>
          </div>
          
          <div className="social-login-buttons">
            <button 
              className="social-btn google"
              onClick={() => handleSocialLogin("google")}
            >
              <FaGoogle /> Continue with Google
            </button>
            
            <button 
              className="social-btn facebook"
              onClick={() => handleSocialLogin("facebook")}
            >
              <FaFacebook /> Continue with Facebook
            </button>
            
            <button 
              className="social-btn tiktok"
              onClick={() => handleSocialLogin("tiktok")}
            >
              <FaTiktok /> Continue with TikTok
            </button>
          </div>
          
          <div className="passwordless-login">
            <p>Don't want to use a password?</p>
            <button 
              className="passwordless-btn"
              onClick={() => handlePasswordlessLogin(formData.email)}
              disabled={!formData.email}
            >
              Email me a magic link
            </button>
          </div>
          
          <p className="auth-link">
            Don't have an account? <Link to="/signup">Sign up here</Link>.
          </p>
          <p className="auth-link">
            <Link to="/forgot-password">Forgot password?</Link>
          </p>
        </div>
      </div>
    </div>
  );
};

export default Login;